from pathlib import Path
import subprocess,json,hashlib,os,random,itertools
r=Path('/home/reinsirk/Atcoder_Env');p=Path(__file__).parent;test=r/'Verify/current/tests/geometry_orientation_test.cpp';sha=lambda b:hashlib.sha256(b).hexdigest();d={'status':'INCOMPLETE','records':[],'fixtures':[],'main_runs':[],'test_sha256':sha(test.read_bytes())}
def turn(a,b,c):return(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])
def crosses(a,b,c,e):return turn(a,b,c)*turn(a,b,e)<0 and turn(c,e,a)*turn(c,e,b)<0
rng=random.Random(99118);counts={True:0,False:0}
while min(counts.values())<32:
 q=[(rng.randint(-100,100),rng.randint(-100,100))for _ in range(4)]
 if len(set(q))<4 or any(turn(*t)==0 for t in itertools.combinations(q,3)):continue
 a,b,c,e=q
 if crosses(a,b,c,e)or crosses(b,c,e,a):continue
 if sum(q[i][0]*q[(i+1)%4][1]-q[i][1]*q[(i+1)%4][0]for i in range(4))<=0:continue
 expected=crosses(a,c,b,e)
 if counts[expected]>=32:continue
 counts[expected]+=1;d['fixtures'].append({'input':''.join(f'{x} {y}\n'for x,y in q),'expected':'Yes\n'if expected else'No\n','reference':'非隣接辺の交差除外/正の靴紐面積で問題の前提を満たし、対角線の真交差で凸性を独立判定。'})
for q in [[(-100,-100),(100,-100),(100,100),(-100,100)],[(0,0),(100,100),(-100,0),(100,-100)]]:
 for i in range(4):
  a=q[i:]+q[:i];d['fixtures'].append({'input':''.join(f'{x} {y}\n'for x,y in a),'expected':'Yes\n'if crosses(a[0],a[2],a[1],a[3])else'No\n','reference':'境界座標と開始頂点の巡回。'})
for cc,compiler in [('gcc',['/usr/bin/g++']),('clang',['clang++','--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15'])]:
 for skip in [False,True]:
  for standard in [False,True]:
   for form,lib in [('full','Geometry/geometory.cpp'),('split','Geometry/Point.cpp')]:
    flags=['-std=c++23','-O2','-Wall','-Wextra','-Werror','-pedantic-errors']
    if skip:flags+=['-DSKIP_RUNTIME_CHECKS']
    if standard:flags+=['-DSIRKIT_FORCE_STANDARD_ARITHMETIC','-DSIRKIT_DISABLE_SIMD','-U__SIZEOF_INT128__']
    exe=p/'reference';cmd=['taskset','-c','10',*compiler,*flags,'-DSIRKIT_ORIENTATION_TEST_HEADER="'+str(r/lib)+'"',str(test),'-o',str(exe)];q=subprocess.run(cmd,capture_output=True,text=True);assert q.returncode==0 and not q.stderr,(cmd,q.stderr);q=subprocess.run(['taskset','-c','10',str(exe)],capture_output=True,text=True);assert q.returncode==0 and not q.stderr,(cmd,q.stdout,q.stderr);d['records'].append({'mode':f'{cc}/{skip}/{standard}/{form}','command':cmd,'stdout':q.stdout});print(cc,skip,standard,form,q.stdout.strip(),flush=True)
for mode,cc,defs in [('gcc',['/usr/bin/g++'],[]),('gcc_standard',['/usr/bin/g++'],['-DSIRKIT_FORCE_STANDARD_ARITHMETIC','-DSIRKIT_DISABLE_SIMD','-U__SIZEOF_INT128__']),('clang',['clang++','--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15'],[])]:
 for form in ['full','split']:
  path=r/f'Verify/current/submissions/geometry_orientation_atcoder_{form}.cpp';exe=p/(mode+'_'+form);cmd=['taskset','-c','6',*cc,'-std=c++23','-O2',*defs,str(path),'-o',str(exe)];subprocess.run(cmd,check=True)
  for i,f in enumerate(d['fixtures']):
   q=subprocess.run(['taskset','-c','10',str(exe)],input=f['input'],capture_output=True,text=True);assert q.returncode==0 and not q.stderr and q.stdout==f['expected'],(mode,form,i,q.stdout,q.stderr);d['main_runs'].append({'mode':mode,'form':form,'fixture':i})
  print(mode,form,'72 valid quadrilateral cases PASS',flush=True)
for standard,skip in [(False,False),(True,True)]:
 flags=['-std=c++23','-O1','-g','-fsanitize=address,undefined','-fno-sanitize-recover=all']
 if skip:flags+=['-DSKIP_RUNTIME_CHECKS']
 if standard:flags+=['-DSIRKIT_FORCE_STANDARD_ARITHMETIC','-DSIRKIT_DISABLE_SIMD','-U__SIZEOF_INT128__']
 exe=p/'san_reference';cmd=['taskset','-c','10','clang++','--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15',*flags,str(test),'-o',str(exe)];q=subprocess.run(cmd,capture_output=True,text=True);assert q.returncode==0,(cmd,q.stderr);q=subprocess.run(['taskset','-c','10',str(exe)],capture_output=True,text=True,env={**os.environ,'ASAN_OPTIONS':'detect_leaks=0','UBSAN_OPTIONS':'halt_on_error=1'});assert q.returncode==0 and not q.stderr,(cmd,q.stdout,q.stderr);d['records'].append({'mode':f'sanitizer/{skip}/{standard}/split','command':cmd,'stdout':q.stdout});print('sanitizer',standard,skip,q.stdout.strip(),flush=True)
d['status']='PASS';(p/'verification.json').write_text(json.dumps(d,indent=2)+'\n')

