#include HEADER
#include <array>
#include <chrono>
#include <cstdint>
#include <iostream>
#include <limits>
#include <random>
#include <string>
#include <vector>
template<class P>int run(int n,int shape,int loops){
 std::mt19937_64 rng(910024);std::vector<std::array<P,3>> items(n);
 for(auto& item:items){
  for(auto& q:item){q.x=static_cast<typename P::Value>(std::int64_t(rng()%2000001)-1000000);q.y=static_cast<typename P::Value>(std::int64_t(rng()%2000001)-1000000);}
  if(shape==1){auto a=item[0],b=item[1];item[2]={2*b.x-a.x,2*b.y-a.y};}
  if(shape==2){for(auto& q:item){q.x=static_cast<typename P::Value>(std::numeric_limits<std::int64_t>::min()+2000000+std::int64_t(q.x));q.y=static_cast<typename P::Value>(std::numeric_limits<std::int64_t>::max()-2000000+std::int64_t(q.y));}}
  if(shape==3){for(auto& q:item){q.x=static_cast<typename P::Value>(std::int64_t(rng()%6000000000000000001ULL)-3000000000000000000);q.y=static_cast<typename P::Value>(std::int64_t(rng()%6000000000000000001ULL)-3000000000000000000);}}
  if(shape==4){const auto k=static_cast<typename P::Value>(2000000000-rng()%1000000);item={P{0,0},P{k,k-1},P{k+1,k}};}
 }
 std::int64_t sum=0;auto start=std::chrono::steady_clock::now();
 for(int k=0;k<loops;++k){auto& q=items[std::size_t(k)%items.size()][0];if constexpr(std::is_integral_v<typename P::Value>)q.x^=1;else q.x+=1.0/16;for(const auto& t:items)sum+=geo::orientation(t[0],t[1],t[2]);}
 auto end=std::chrono::steady_clock::now();std::cout<<std::chrono::duration<double,std::milli>(end-start).count()<<' '<<sum<<'\n';return 0;
}
int main(int argc,char**argv){if(argc!=5)return 1;const auto engine=std::string(argv[1]);int n=std::stoi(argv[2]),shape=std::stoi(argv[3]),loops=std::stoi(argv[4]);if(engine=="floating")return run<geo::Point<double>>(n,shape,loops);if(engine=="standard")return run<geo::Point<std::int64_t,std::int64_t>>(n,shape,loops);return run<geo::PointI>(n,shape,loops);}

